INSERT INTO feature VALUES('run-prefixes','sessions','Recorded prefixes (Prefix(S))','session-types','implemented','notable',NULL,'A record of the moves a protocol admits so far, open or complete, is a `Prefix(S)`, checked by the monitor that admits runs, a move the protocol refuses refused by name; `Run(S)` holds only complete runs, and no prefix converts to one. An open prefix rides forward along a session flow and stays open, by conversion and on the machine, a move the flow''s target refuses refused at that move.','core-term core-checker core-session surface-lowering','corpus/model/sessions/seat-prefix.gandr corpus/pathological/sessions/seat-prefix.gandr crates/core-checker-base/tests/flow.rs::a_prefix_admits_an_open_run_and_refuses_by_move corpus/model/sessions/seat-prefix-evolution.gandr corpus/pathological/sessions/seat-prefix-evolution.gandr crates/core-checker-base/src/flow/tests.rs::a_prefix_rides_forward_and_refuses_by_move','corpus/model/sessions/seat-prefix.gandr',NULL);
